MOTIF_NAME = 'restricted_opponent_pieces'
MOTIF_DESCRIPTION = 'The side to move has more opponent pieces (queen, rooks, bishops, knights) on ranks 1-2 from their perspective than the opponent has restricted pieces on the side-to-move side, indicating a space advantage cramping the opponent.'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    # Count opponent pieces restricted to their home ranks (1-2 from their own side)
    stm_restricted = 0
    opp_restricted = 0

    for sq in chess.SQUARES:
        piece = board.piece_at(sq)
        if piece is None:
            continue
        if piece.piece_type == chess.PAWN or piece.piece_type == chess.KING:
            continue

        rank = chess.square_rank(sq)
        if piece.color == opp:
            # From opponent's perspective, ranks 0-1 are home ranks
            if piece.color == chess.WHITE:
                if rank <= 1:
                    stm_restricted += 1
            else:
                if rank >= 6:
                    stm_restricted += 1
        elif piece.color == stm:
            if piece.color == chess.WHITE:
                if rank <= 1:
                    opp_restricted += 1
            else:
                if rank >= 6:
                    opp_restricted += 1

    return stm_restricted > opp_restricted and stm_restricted >= 1
